import { readFile, writeFile } from "node:fs/promises";

const source = new URL("../prisma/schema.prisma", import.meta.url);
const destination = new URL("../prisma/schema.production.prisma", import.meta.url);
const schema = await readFile(source, "utf8");
const production = schema.replace('provider = "sqlite"', 'provider = "postgresql"');

if (production === schema) {
  throw new Error("Could not locate the SQLite datasource in prisma/schema.prisma.");
}

await writeFile(destination, [
  "// Generated by scripts/prepare-production-schema.mjs. Do not edit directly.",
  production
].join("\n"));
